mapper.select:
SELECT *
FROM smartbusmngdb.sbm_facility_ad
WHERE facility_id = #{facilityId}
  AND group_id = #{userGroupId}
ORDER BY ad_id

mapper.update:
UPDATE smartbusmngdb.sbm_facility_ad
SET
    last_updt_dt = NOW(),
    last_user_id = #{lastUserId},
    last_regist_tool = #{lastRegistProgrm}
WHERE facility_id = #{facilityId}
  AND ad_id = #{adId}
  AND group_id = #{groupId}

mapper.delete:
DELETE FROM smartbusmngdb.sbm_facility_ad
WHERE facility_id = #{facilityId}
  AND group_id = #{userGroupId}

DELETE FROM smartbusmngdb.sbm_facility_ad
WHERE facility_id = #{facilityId}
  AND ad_id = #{adId}
  AND group_id = #{groupId}

mapper.select:
SELECT a.ad_id AS adId, a.group_id AS groupId, a.ad_title AS adTitle, a.ad_tp AS adTp, a.default_tp AS adDefault, a.use_tp AS useTp, a.sta_de AS eventSd, a.eta_de AS eventEd, a.sta_hr AS eventSt, a.eta_hr AS eventEt, a.line_news AS adOneline FROM smartbusmngdb.sbm_ad a JOIN ( SELECT ad_id FROM smartbusmngdb.sbm_facility_ad WHERE facility_id IN
#{fId}
AND group_id = #{userGroupId}
GROUP BY ad_id HAVING COUNT(DISTINCT facility_id) = #{facilityCnt} ) facAd ON a.ad_id = facAd.ad_id
